CREATE EXTENSION IF NOT EXISTS pg_cron;

SELECT cron.schedule(
  'delete-old-zl-included-users',
  '* * * * *',
  $$DELETE FROM zl_included_users WHERE created_at < NOW() - INTERVAL '5 minutes'$$
);

SELECT cron.alter_job(
  job_id := (SELECT jobid FROM cron.job WHERE jobname = 'delete-old-zl-included-users'),
  active := false
);

SELECT cron.alter_job(
  job_id := (SELECT jobid FROM cron.job WHERE jobname = 'delete-old-zl-included-users'),
  active := true
);

